        "min_area": 60,
        "note": "来源:zlj|zrg (共6间, 每间60~80㎡)"
      },
      {
        "room_type": "办公室",
        "min_area": 40,
        "note": "来源:zlj|zrg (共2间, 每间40㎡)"
