        "min_area": 350,
        "note": "来源:gb_standard|博物馆建筑设计规范 条文说明 (参考案例数据)"
      }
    ],
    "safety_specs": [
      "[无具体证据]"
    ]
  },
  "activity_programming": {
    "trends": [
      {
        "activity_name": "Live Science Theater & Demonstrations",
        "spatial_need": "Dedicated Science Show Theatre (e.g., Floor 1) or flexible stage areas for live performances",
        "reference_case": "Glasgow Science Centre, Glasgow; CERN Science Gateway, Geneva; Pacific Science Center, Seattle",
        "is_general_knowledge": false
      },
      {
        "activity_name": "Hands-on Maker & Laboratory Workshops",
        "spatial_need": "Specialized workshop spaces (e.g., 'The Lab', 'The Bothy') or a Science Education Center equipped for construction and programming",
        "reference_case": "Glasgow Science Centre, Glasgow; National Science Museum, Daejeon; CERN Science Gateway, Geneva",
        "is_general_knowledge": false
      },
      {
        "activity_name": "Intensive Science Camps & Study Tours",
        "spatial_need": "Multi-purpose classrooms or education centers capable of hosting week-long classes and summer programs",
        "reference_case": "California Science Center, Los Angeles; Pacific Science Center, Seattle; The Franklin Institute, Philadelphia",
        "is_general_knowledge": false
      },
      {
        "activity_name": "STEM Career Exploration & Youth Development",
        "spatial_need": "Interactive hubs (e.g., 'My World of Work Live') or collaborative spaces for teen interns and career programs",
        "reference_case": "Glasgow Science Centre, Glasgow; The Franklin Institute, Philadelphia; California Science Center, Los Angeles",
        "is_general_knowledge": false
      }
    ],
    "suggested_curriculum_zones": [
      "Science Show Theatre",
      "The Lab (Interactive Workshops)",
      "The Bothy (Workshop Space)",
      "Science Education Center",
      "My World of Work Live Hub",
      "CERN Lab Workshops Zone"
    ]
  },
